<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;
Auth::requireLogin();$id=(int)($_GET['id']??0);$pdo=Database::connection();$settings=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $r)$settings[$r['setting_key']]=$r['setting_value'];$q=$pdo->prepare("SELECT o.*,t.table_number,u.name cashier_name FROM orders o LEFT JOIN restaurant_tables t ON t.id=o.table_id LEFT JOIN users u ON u.id=o.cashier_id WHERE o.id=?");$q->execute([$id]);$o=$q->fetch();if(!$o){http_response_code(404);exit('Order tidak ditemukan.');}$q=$pdo->prepare('SELECT * FROM order_items WHERE order_id=? ORDER BY id');$q->execute([$id]);$items=$q->fetchAll();$m=$pdo->prepare('SELECT * FROM order_item_modifiers WHERE order_item_id=? ORDER BY id');foreach($items as &$it){$m->execute([$it['id']]);$it['modifiers']=$m->fetchAll();}unset($it);$q=$pdo->prepare('SELECT * FROM payments WHERE order_id=? ORDER BY paid_at,id');$q->execute([$id]);$payments=$q->fetchAll();$q=$pdo->prepare('SELECT * FROM refunds WHERE order_id=? ORDER BY processed_at,id');$q->execute([$id]);$refunds=$q->fetchAll();function rp($n){return 'Rp '.number_format((float)$n,0,',','.');}$w=in_array((int)($settings['receipt_width']??80),[58,80],true)?(int)$settings['receipt_width']:80;
?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Struk <?=htmlspecialchars($o['order_no'])?></title><style>body{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;background:#eee;margin:0;padding:20px;color:#222}.receipt{width:<?=$w?>mm;max-width:100%;margin:auto;background:#fff;padding:6mm;box-shadow:0 10px 30px #bbb}.center{text-align:center}.brand{font-size:20px;font-weight:800}.muted{color:#666;font-size:10px}.line{border-top:1px dashed #777;margin:9px 0}.row{display:flex;justify-content:space-between;gap:10px;font-size:11px;padding:2px 0}.row strong{white-space:nowrap}.item{font-size:11px;margin:6px 0}.mods{font-size:9px;color:#666;padding-left:8px}.total{font-size:14px;font-weight:800}.no-print{display:flex;justify-content:center;margin:18px}.btn{padding:10px 16px;border:0;border-radius:8px;background:#e8672b;color:#fff;font-weight:700}@media print{body{background:#fff;padding:0}.receipt{box-shadow:none;width:<?=$w?>mm}.no-print{display:none}}</style></head><body><div class="receipt"><div class="center"><div class="brand"><?=htmlspecialchars(strtoupper($settings['restaurant_name']??'Kedai Bara'))?></div><div class="muted"><?=htmlspecialchars($settings['restaurant_tagline']??'')?><br><?=nl2br(htmlspecialchars($settings['restaurant_address']??''))?></div></div><div class="line"></div><div class="muted">Order: <?=htmlspecialchars($o['order_no'])?><br>Waktu: <?=htmlspecialchars($o['created_at'])?><br><?=$o['table_number']?'Meja: '.htmlspecialchars($o['table_number']).'<br>':''?>Pelanggan: <?=htmlspecialchars($o['customer_name']?:'Guest')?></div><div class="line"></div><?php foreach($items as $i):if(in_array($i['status'],['voided','cancelled'],true))continue;?><div class="item"><div><?=htmlspecialchars($i['item_name'])?></div><?php if($i['modifiers']):?><div class="mods"><?=htmlspecialchars(implode(', ',array_column($i['modifiers'],'option_name')))?></div><?php endif;?><div class="row"><span><?=number_format((float)$i['quantity'],0)?> × <?=rp($i['unit_price'])?></span><strong><?=rp($i['subtotal'])?></strong></div></div><?php endforeach;?><div class="line"></div><div class="row"><span>Subtotal</span><strong><?=rp($o['subtotal'])?></strong></div><?php if($o['discount_amount']>0):?><div class="row"><span>Diskon</span><strong>-<?=rp($o['discount_amount'])?></strong></div><?php endif;?><?php if($o['tax_amount']>0):?><div class="row"><span>Tax</span><strong><?=rp($o['tax_amount'])?></strong></div><?php endif;?><?php if($o['service_amount']>0):?><div class="row"><span>Service</span><strong><?=rp($o['service_amount'])?></strong></div><?php endif;?><div class="row total"><span>TOTAL</span><strong><?=rp($o['total'])?></strong></div><div class="line"></div><?php foreach($payments as $p):?><div class="row"><span><?=strtoupper(htmlspecialchars($p['method']))?></span><strong><?=rp($p['amount'])?></strong></div><?php endforeach;?><?php foreach($refunds as $r):?><div class="row"><span>REFUND <?=strtoupper(htmlspecialchars($r['method']))?></span><strong>-<?=rp($r['amount'])?></strong></div><?php endforeach;?><div class="line"></div><div class="center muted">Kasir: <?=htmlspecialchars($o['cashier_name']?:'-')?><br><?=nl2br(htmlspecialchars($settings['receipt_footer']??'Terima kasih telah berkunjung.'))?></div></div><div class="no-print"><button class="btn" onclick="window.print()">Print Struk</button></div></body></html>
